public class MaquinaPoporopos extends Maquina {
	protected int porciones;
	protected boolean carrito;

	
	public MaquinaPoporopos() {
		super();
		porciones = 0;
		carrito = false;
	}
	
	public MaquinaPoporopos(String codigo, String marca, String modelo, float tarifa, int porciones, boolean carrito) {
		super(codigo, marca, modelo, tarifa);
		this.porciones = porciones;
		this.carrito = carrito;
	}
	
	public void setPorciones(int newPorciones) {
		porciones = newPorciones;
	}
	
	public int getPorciones() {
		return porciones;
	}
	
	public void setCarrito(boolean newCarrito) {
		carrito = newCarrito;
	}
	
	public boolean getCarrito() {
		return carrito;
	}
	
	@Override
	public float Cotizacion(int dias) {
		float total = tarifa * dias;

		if (carrito) {
			total += 40 * dias;
		}

		return total;
	}
	
	@Override
	public String getTipo() {
		return "Poporopos";
	}

	@Override
	public void mostrarCaracteristicas() {
    	System.out.println("Porciones por hora: " + porciones);
    	System.out.println("Carrito: " + carrito);
	}
}
